1: <!--
2: 	ALE-394: the Reschedule dialog — date, start time and venue, the Payment
3: 	Cutoff and (while Batch 1 hasn't gone out) the contact-from date, both
4: 	prefilled with the offsets Phoenix keeps and following a new date or time
5: 	until edited. It says how many people the reschedule emails before saving.
6: 	Phoenix decides: it is refused only after finalisation or cancellation.
7: -->
8: <script lang="ts">
9: import type { BeginnersWorkshop } from "@dhc/api-client";
10: import type { DateValue } from "@internationalized/date";
11: import { toast } from "svelte-sonner";
12: import {
13: 	civilCalendarDate,
14: 	dublinToday,
15: 	formatCivilDate,
16: } from "#lib/club-calendar.js";
17: import {
18: 	keptContactFrom,
19: 	keptCutoff,
20: 	rescheduleWarning,
21: } from "#lib/beginners-workshops/reschedule.js";
22: import { Button } from "#lib/components/ui/button/index.js";
23: import DatePicker from "#lib/components/ui/date-picker.svelte";
24: import * as Dialog from "#lib/components/ui/dialog/index.js";
25: import * as Field from "#lib/components/ui/field/index.js";
26: import { Input } from "#lib/components/ui/input/index.js";
27: import DestinationInput from "#lib/components/destination-input.svelte";
28: import {
29: 	rescheduleWorkshopSchema,
30: 	VENUE_MAX,
31: } from "#lib/schemas/beginnersWorkshop.js";
32: import { rescheduleWorkshop } from "./console.remote";
33: import WorkshopDialog from "#lib/components/beginners-workshops/workshop-dialog.svelte";
34: import * as Alert from "#lib/components/ui/alert/index.js";
35: 
36: let {
37: 	workshop,
38: 	recipients,
39: 	open = $bindable(false),
40: 	today = dublinToday(),
41: }: {
42: 	workshop: BeginnersWorkshop;
43: 	recipients: number;
44: 	open?: boolean;
45: 	/** Dublin today (`YYYY-MM-DD`); injectable for tests. */
46: 	today?: string;
47: } = $props();
48: 
49: const form = $derived(rescheduleWorkshop.for(workshop.id));
50: let formError = $state<string | null>(null);
51: // Once edited, a field no longer follows the new date and time.
52: let cutoffEdited = $state(false);
53: let contactFromEdited = $state(false);
54: 
55: const warning = $derived(rescheduleWarning(recipients));
56: 
57: type DateKey = "date" | "paymentCutoffDate" | "contactFromDate";
58: 
59: function current(key: "date" | "startTime"): string {
60: 	return form.fields[key].value() || workshop[key];
61: }
62: 
63: function pickerValue(key: DateKey, fallback: string): DateValue | undefined {
64: 	return civilCalendarDate(form.fields[key].value() || fallback);
65: }
66: 
67: // The kept offsets for the date and start time now in the form.
68: function follow(date: string, startTime: string) {
69: 	const cutoff = keptCutoff(workshop, date, startTime);
70: 	if (!cutoffEdited) {
71: 		form.fields.paymentCutoffDate.set(cutoff.date);
72: 		form.fields.paymentCutoffTime.set(cutoff.time);
73: 	}
74: 	if (workshop.contactFromEditable && !contactFromEdited) {
75: 		const cutoffDate = form.fields.paymentCutoffDate.value() || cutoff.date;
76: 		form.fields.contactFromDate.set(
77: 			keptContactFrom(workshop, date, cutoffDate, today),
78: 		);
79: 	}
80: }
81: 
82: function setWorkshopDate(value: DateValue | undefined) {
83: 	if (!value) return;
84: 	form.fields.date.set(value.toString());
85: 	follow(value.toString(), current("startTime"));
86: }
87: 
88: function setCutoffDate(value: DateValue | undefined) {
89: 	if (!value) return;
90: 	cutoffEdited = true;
91: 	form.fields.paymentCutoffDate.set(value.toString());
92: }
93: 
94: function setContactFrom(value: DateValue | undefined) {
95: 	if (!value) return;
96: 	contactFromEdited = true;
97: 	form.fields.contactFromDate.set(value.toString());
98: }
99: </script>
100: 
101: <Dialog.Root bind:open>
102: 	<WorkshopDialog>
103: 		<Dialog.Header>
104: 			<Dialog.Title>Reschedule {formatCivilDate(workshop.date)}</Dialog.Title>
105: 			<Dialog.Description>
106: 				Change the date, time or venue. Existing bookings stay confirmed and the
107: 				number of places stays the same.
108: 			</Dialog.Description>
109: 		</Dialog.Header>
110: 
111: 		<form
112: 			{...form.preflight(rescheduleWorkshopSchema).enhance(async (instance) => {
113: 				formError = null;
114: 				if (!(await instance.submit())) return;
115: 				const result = instance.result;
116: 				if (result?.ok) {
117: 					toast.success("Workshop rescheduled");
118: 					open = false;
119: 				} else if (result) {
120: 					formError = result.error;
121: 				}
122: 			})}
123: 			class="grid gap-5"
124: 			aria-label="Reschedule workshop"
125: 		>
126: 			<input {...form.fields.id.as("hidden", workshop.id)} />
127: 
128: 			<h3 class="text-base font-semibold">New workshop details</h3>
129: 			<Field.Group class="grid gap-4 sm:grid-cols-[1fr_10rem_10rem]">
130: 				<Field.Field>
131: 					{@const { value: _date, ...props } = form.fields.date.as(
132: 						"text",
133: 						workshop.date,
134: 					)}
135: 					<Field.Label for={props.name}>New date</Field.Label>
136: 					<DatePicker
137: 						{...props}
138: 						id={props.name}
139: 						label="New date"
140: 						value={pickerValue("date", workshop.date)}
141: 						onValueChange={setWorkshopDate}
142: 					/>
143: 					{#each form.fields.date.issues() as issue (issue.message)}
144: 						<Field.Error>{issue.message}</Field.Error>
145: 					{/each}
146: 				</Field.Field>
147: 				<Field.Field>
148: 					{@const props = form.fields.startTime.as("time", workshop.startTime)}
149: 					<Field.Label for={props.name}>Start</Field.Label>
150: 					<Input
151: 						{...props}
152: 						id={props.name}
153: 						oninput={(event) =>
154: 							follow(current("date"), event.currentTarget.value)}
155: 					/>
156: 					{#each form.fields.startTime.issues() as issue (issue.message)}
157: 						<Field.Error>{issue.message}</Field.Error>
158: 					{/each}
159: 				</Field.Field>
160: 				<Field.Field>
161: 					{@const props = form.fields.endTime.as(
162: 						"time",
163: 						workshop.endTime ?? "",
164: 					)}
165: 					<Field.Label for={props.name}>End time</Field.Label>
166: 					<Input {...props} id={props.name} />
167: 					{#each form.fields.endTime.issues() as issue (issue.message)}
168: 						<Field.Error>{issue.message}</Field.Error>
169: 					{/each}
170: 				</Field.Field>
171: 			</Field.Group>
172: 
