174: 				{@const props = form.fields.venue.as("text", workshop.venue)}
175: 				<Field.Label for={props.name}>Venue</Field.Label>
176: 				<Input {...props} id={props.name} maxlength={VENUE_MAX} />
177: 				{#each form.fields.venue.issues() as issue (issue.message)}
178: 					<Field.Error>{issue.message}</Field.Error>
179: 				{/each}
180: 			</Field.Field>
