199: 					<DatePicker
200: 						{...props}
201: 						id={props.name}
202: 						label="Payment deadline date"
203: 						value={pickerValue("paymentCutoffDate", workshop.paymentCutoffDate)}
204: 						onValueChange={setCutoffDate}
205: 					/>
206: 					<Field.Description
207: 						>Moves with the workshop date until you edit it.</Field.Description
208: 					>
209: 					{#each form.fields.paymentCutoffDate.issues() as issue (issue.message)}
210: 						<Field.Error>{issue.message}</Field.Error>
211: 					{/each}
212: 				</Field.Field>
213: 				<Field.Field>
214: 					{@const props = form.fields.paymentCutoffTime.as(
